module JC_counter (
    input                clk,
    input                rst_n,
    output reg [63:0]     Q
);

    parameter RESET = 64'h0;
    parameter IDLE = 64'hFFFFFFFFFFFFFFFE;

    reg [63:0] next_Q;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            Q <= RESET;
        end else begin
            Q <= next_Q;
        end
    end

    always @(*) begin
        next_Q = Q;
        if (Q[0] == 0) begin
            next_Q = {~Q[0], Q[63:1]};
        end else begin
            next_Q = {~Q[0], Q[63:1]};
        end
    end

endmodule
